import{_ as a,o as e,c as s,a0 as i}from"./chunks/framework.BC4nTfYq.js";const u=JSON.parse('{"title":"第 10 章 · 最佳实践与进阶方向","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/10-best-practices.md","filePath":"chapters/10-best-practices.md","lastUpdated":1792595797000}'),l={name:"chapters/10-best-practices.md"};function n(r,t,d,o,c,p){return e(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="第-10-章-·-最佳实践与进阶方向" tabindex="-1">第 10 章 · 最佳实践与进阶方向 <a class="header-anchor" href="#第-10-章-·-最佳实践与进阶方向" aria-label="Permalink to &quot;第 10 章 · 最佳实践与进阶方向&quot;">​</a></h1><div class="ani-panel"><img src="https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=anime%20style%20graduation%20ceremony%20on%20a%20floating%20island%2C%20girl%20in%20academic%20cap%20holding%20a%20glowing%20diploma%20scroll%2C%20friends%20waving%2C%20rainbow%20and%20airships%20sailing%20toward%20new%20horizons%2C%20celebration%2C%20kawaii&amp;image_size=landscape_16_9" alt="结业典礼"><p class="ani-caption">小塔：「恭喜走到这里！最后一章不教 API，我们把前九章的经验沉淀成清单和地图，然后……旅程才刚刚开始。」</p></div><h2 id="本章学习目标" tabindex="-1">本章学习目标 <a class="header-anchor" href="#本章学习目标" aria-label="Permalink to &quot;本章学习目标&quot;">​</a></h2><ul><li>沉淀架构 / 安全 / 性能 / 工程化四张实践清单</li><li>明确技术选型的判断标准（而不是背答案）</li><li>拿到结业后的进阶功能地图与学习资源</li></ul><h2 id="_10-1-架构最佳实践" tabindex="-1">10.1 架构最佳实践 <a class="header-anchor" href="#_10-1-架构最佳实践" aria-label="Permalink to &quot;10.1 架构最佳实践&quot;">​</a></h2><h3 id="命令分层-commands-要薄-服务要厚" tabindex="-1">命令分层：commands 要薄，服务要厚 <a class="header-anchor" href="#命令分层-commands-要薄-服务要厚" aria-label="Permalink to &quot;命令分层：commands 要薄，服务要厚&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>commands/   只做：参数接收 -&gt; 调用 service -&gt; 序列化结果/错误</span></span>
<span class="line"><span>services/   业务规则、状态、持久化（本教程的 NotesStore / NotesStorage）</span></span></code></pre></div><p>命令层不要堆业务逻辑——否则同一规则被多个入口（命令/事件/导入）复制后必然漂移。 本教程第 8 章的导入功能复用 <code>store.insert</code> 就是这条原则的示范。</p><h3 id="状态管理" tabindex="-1">状态管理 <a class="header-anchor" href="#状态管理" aria-label="Permalink to &quot;状态管理&quot;">​</a></h3><ul><li>Rust 端共享状态走 <code>Mutex</code>/<code>RwLock</code>，锁粒度要小、<strong>不要嵌套加锁</strong>（本应用三把独立锁）；</li><li>写流程保持「先持久化成功，再改内存」，崩溃后内存可从磁盘重建；</li><li>前端单一数据源（composable），组件不直接持有业务状态；</li><li>跨语言边界只传 DTO（serde 结构），不传 Rust 引用或前端对象。</li></ul><h3 id="错误处理选型" tabindex="-1">错误处理选型 <a class="header-anchor" href="#错误处理选型" aria-label="Permalink to &quot;错误处理选型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>工具</th><th>适用</th></tr></thead><tbody><tr><td><code>Result&lt;T, String&gt;</code></td><td>命令边界：错误要直接展示给用户（教学阶段最清晰）</td></tr><tr><td><code>thiserror</code></td><td>库/服务层：定义领域错误枚举，<code>#[from]</code> 自动转换</td></tr><tr><td><code>anyhow</code></td><td>应用内部、一次性脚本：不关心错误类型时</td></tr></tbody></table><p>正式项目推荐：服务层 <code>thiserror</code> 枚举 → 命令边界统一转成用户可读消息/错误码。</p><h2 id="_10-2-安全清单" tabindex="-1">10.2 安全清单 <a class="header-anchor" href="#_10-2-安全清单" aria-label="Permalink to &quot;10.2 安全清单&quot;">​</a></h2><p>发布前逐项过：</p><ul><li>[ ] <strong>权限最小化</strong>：capability 里每个权限都能说出用途；不用 <code>*</code> 通配；</li><li>[ ] <strong>CSP</strong>：无远程域名通配，禁内联脚本；新增外部依赖时按指令精确放开；</li><li>[ ] <strong>路径穿越</strong>：用户输入进入路径前过滤/规范化（storage 的 <code>[a-zA-Z0-9-]</code> 白名单）；</li><li>[ ] <strong>命令注入</strong>：非必要不碰 shell；必须用时参数走数组形式，绝不拼接字符串；</li><li>[ ] <strong>敏感数据</strong>：令牌不要明文写配置；考虑系统 keychain（keyring crate）；</li><li>[ ] <strong>更新信任链</strong>：私钥只在 CI secrets；发布产物不可变，不覆盖已发布包；</li><li>[ ] <strong>依赖卫生</strong>：定期更新、关注安全公告；前端同样做审计。</li></ul><p>一条总原则：<strong>所有跨边界输入（前端参数、文件内容、URL、环境变量）都是不可信的</strong>， 在边界处校验，内部才能保持简单。</p><h2 id="_10-3-性能清单" tabindex="-1">10.3 性能清单 <a class="header-anchor" href="#_10-3-性能清单" aria-label="Permalink to &quot;10.3 性能清单&quot;">​</a></h2><ul><li>[ ] 命令默认异步；CPU/IO 重活使用 <code>spawn_blocking</code>，不阻塞主线程；</li><li>[ ] 长任务用事件上报进度，而不是让用户盯着转圈；</li><li>[ ] 前端输入防抖、大列表虚拟化、重依赖懒加载；</li><li>[ ] release profile 启用 LTO / strip（第 7 章）；</li><li>[ ] 用数据说话：先测量（devtools Performance、日志时间戳）再优化，拒绝玄学；</li><li>[ ] 控制序列化边界的体积：列表接口不要返回大字段全量。</li></ul><h2 id="_10-4-工程化清单" tabindex="-1">10.4 工程化清单 <a class="header-anchor" href="#_10-4-工程化清单" aria-label="Permalink to &quot;10.4 工程化清单&quot;">​</a></h2><ul><li>[ ] 语义化版本：三平台版本号一致，tag 与版本一致；</li><li>[ ] CI 三平台矩阵每次合并都跑（编译 + 前端检查）；</li><li>[ ] 发布走 tag 触发的固定流程，不在本地手工打包（可复现 &gt; 方便）；</li><li>[ ] 密钥/证书集中管理，成员变动时可轮换；</li><li>[ ] 变更记录（Release Notes）面向用户写，不贴 commit 流水账；</li><li>[ ] 重大变更分小步提交——本教程每章一个版本，随时可回滚到任意学习节点。</li></ul><h2 id="_10-5-进阶功能地图" tabindex="-1">10.5 进阶功能地图 <a class="header-anchor" href="#_10-5-进阶功能地图" aria-label="Permalink to &quot;10.5 进阶功能地图&quot;">​</a></h2><p>按「与本教程的距离」排序，学完即可上手：</p><table tabindex="0"><thead><tr><th>方向</th><th>要点</th><th>提示</th></tr></thead><tbody><tr><td>多窗口</td><td>Window/label、窗口间事件通信</td><td>复用第 3 章事件知识</td></tr><tr><td>系统托盘</td><td>tray icon、菜单、最小化到托盘</td><td><code>TrayIconBuilder</code></td></tr><tr><td>全局快捷键</td><td>注册/注销组合键</td><td><code>global-shortcut</code> 插件</td></tr><tr><td>深度链接</td><td>注册 URL scheme，从浏览器唤起应用</td><td><code>deep-link</code> 插件</td></tr><tr><td>剪贴板</td><td>读写剪贴板</td><td><code>clipboard-manager</code> 插件</td></tr><tr><td>本地数据库</td><td>SQLite（连接池、迁移）</td><td><code>tauri-plugin-sql</code> 或 rusqlite</td></tr><tr><td>自绘标题栏</td><td><code>decorations: false</code> + 自绘按钮 + 拖拽区域</td><td>先确认产品真的需要</td></tr><tr><td>移动端</td><td>Tauri Mobile：iOS/Android 目标</td><td>复用大部分 Rust，前端需适配触控与小屏</td></tr><tr><td>嵌入式 Web/Bay 扩展</td><td>WebAssembly、调用本地 AI 模型</td><td>资源走 bundle.resources</td></tr></tbody></table><p>每个方向都沿用同一套心智模型：<strong>官方插件 → 注册 → capability 授权 → 前端封装 → 错误/日志补齐</strong>。</p><h2 id="_10-6-推荐学习资源" tabindex="-1">10.6 推荐学习资源 <a class="header-anchor" href="#_10-6-推荐学习资源" aria-label="Permalink to &quot;10.6 推荐学习资源&quot;">​</a></h2><ul><li>Tauri 官方文档（v2）：配置 schema 与插件权限的最终权威；</li><li>Tauri GitHub Examples：每个插件的最小可运行示例；</li><li>Rust 官方学习资料：所有权、生命周期、异步运行时——Rust 基础决定 Tauri 天花板；</li><li>各平台开发者文档：WebView2 / WKWebView / WebKitGTK 的行为差异以官方为准。</li></ul><h2 id="_10-7-结业寄语" tabindex="-1">10.7 结业寄语 <a class="header-anchor" href="#_10-7-结业寄语" aria-label="Permalink to &quot;10.7 结业寄语&quot;">​</a></h2><p>回顾这条学习路径：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第 1 章  环境与第一个窗口</span></span>
<span class="line"><span>第 2 章  界面与命令（前后端边界）</span></span>
<span class="line"><span>第 3 章  事件系统（双向通信）</span></span>
<span class="line"><span>第 4 章  文件系统（数据持久化）</span></span>
<span class="line"><span>第 5 章  系统 API（融入操作系统）</span></span>
<span class="line"><span>第 6 章  多端兼容（一致性工程）</span></span>
<span class="line"><span>第 7 章  打包发布（工程产出）</span></span>
<span class="line"><span>第 8 章  自动更新（可信的远程演进）</span></span>
<span class="line"><span>第 9 章  调试与排障（科学方法）</span></span>
<span class="line"><span>第 10 章 最佳实践（沉淀与出发）</span></span></code></pre></div><p>你已经不只是「会用 Tauri」，而是完整走过了一个桌面应用<strong>从创建到可信分发</strong>的生命周期。 带着 AniNotes 去做你自己的作品吧——遇到新问题，就用第 9 章的方法取证，用第 10 章的清单决策。</p><p><strong>祝构建顺利，Rust 永绿。🎀</strong></p><hr><p><strong>上一章</strong>：<a href="./09-debugging.html">第 9 章 · 调试技巧与常见问题</a><strong>回到</strong>：<a href="/tauri-app-tutorial-site/">文档首页</a></p>`,34)])])}const g=a(l,[["render",n]]);export{u as __pageData,g as default};
